import {STOCK_FIRE_RED_SHA} from './verified-frlg.js';
import {decodeWave,writeWave} from './pcm-sample.js';
import {CRY_NAMES} from './cry-names.js';
const BASE=0x08000000,COUNT=388;
export function cryProfile(hash){if(hash===STOCK_FIRE_RED_SHA)return{table:0x48c914,count:COUNT};throw Error('The selected ROM supports no compatible native cry table.');}
export function readCries(reader,hash){const profile=cryProfile(hash),v=new DataView(reader.bytes.buffer,reader.bytes.byteOffset,reader.bytes.byteLength);if(profile.table+COUNT*24>reader.bytes.length)throw Error('Incomplete native cry table.');const rows=[];
 for(let id=0;id<COUNT;id++){const at=profile.table+id*12,reverse=at+COUNT*12;for(const [row,type]of [[at,0x20],[reverse,0x30]])if(v.getUint32(row,true)!==(type|60<<8)||v.getUint32(row+8,true)!==0x00ff00ff)throw Error('Native cry tone layout failed verification.');if(v.getUint32(at+4,true)!==v.getUint32(reverse+4,true))throw Error('Normal and reverse cry samples differ.');const address=v.getUint32(at+4,true)-BASE,sample=decodeWave(reader,address);if(sample.status||sample.loopStart)throw Error('Looped cries are unsupported.');rows.push({id,name:CRY_NAMES[id],address,at,reverse,rate:sample.rate,count:sample.pcm.length});}
 return{profile,rows};
}
export function validateCryEdits(edits){if(edits===undefined)return;if(!edits||Array.isArray(edits)||Object.keys(edits).length>16)throw Error('Invalid cry edits.');let total=0;for(const [hash,rows]of Object.entries(edits)){cryProfile(hash);if(!rows||Array.isArray(rows)||Object.keys(rows).length>COUNT)throw Error('Invalid cry edits.');for(const [id,s]of Object.entries(rows)){if(!/^(0|[1-9]\d*)$/.test(id)||+id>=COUNT||!s||!Number.isInteger(s.rate)||s.rate<4000||s.rate>32000||!Array.isArray(s.pcm)||!s.pcm.length||s.pcm.length>65536||s.pcm.length/s.rate>3||s.pcm.some(n=>!Number.isInteger(n)||n<0||n>255))throw Error('Invalid cry sample.');total+=s.pcm.length;}}if(total>1e6)throw Error('The project cry budget is 1 MB of sample data.');}
export function installCries(project,reader,hash,output){const rows=project.cryEdits?.[hash];if(!rows||!Object.keys(rows).length)return[];validateCryEdits({[hash]:rows});const native=readCries(reader,hash),reports=[];for(const [id,sample]of Object.entries(rows)){const row=native.rows[+id],at=output.allocate(writeWave(sample),'Cry: '+row.name);// PCM uses plain/reverse tones; keeping the DPCM bit would silence normal playback.
output.write(row.at,Uint8Array.of(0));output.write(row.reverse,Uint8Array.of(0x10));output.int(row.at+4,BASE+at);output.int(row.reverse+4,BASE+at);reports.push('Cry: '+row.name+' · normal and reverse modes');}return reports;}
